CREATE TABLE event_counts AS SELECT 'wording' endpoint,'overall' dimension,'all' grp,duration,COUNT(*) exits,SUM(event) deaths FROM facts WHERE kind='prose' GROUP BY 'all',duration UNION ALL SELECT 'wording' endpoint,'cohort' dimension,CAST(cohort AS CHAR) grp,duration,COUNT(*) exits,SUM(event) deaths FROM facts WHERE kind='prose' AND cohort BETWEEN 2004 AND 2024 GROUP BY CAST(cohort AS CHAR),duration UNION ALL SELECT 'wording' endpoint,'editor' dimension,editor_group grp,duration,COUNT(*) exits,SUM(event) deaths FROM facts WHERE kind='prose' GROUP BY editor_group,duration UNION ALL SELECT 'wording' endpoint,'length' dimension,length_bucket grp,duration,COUNT(*) exits,SUM(event) deaths FROM facts WHERE kind='prose' GROUP BY length_bucket,duration UNION ALL SELECT 'wording' endpoint,'kind' dimension,kind grp,duration,COUNT(*) exits,SUM(event) deaths FROM facts WHERE 1=1 GROUP BY kind,duration UNION ALL SELECT 'wording_raw' endpoint,'overall' dimension,'all' grp,duration,COUNT(*) exits,SUM(raw_event) deaths FROM facts WHERE kind='prose' GROUP BY 'all',duration UNION ALL SELECT 'slot' endpoint,'overall' dimension,'all' grp,duration,COUNT(*) exits,SUM(event) deaths FROM slot_facts WHERE kind='prose' GROUP BY 'all',duration UNION ALL SELECT 'slot' endpoint,'cohort' dimension,CAST(cohort AS CHAR) grp,duration,COUNT(*) exits,SUM(event) deaths FROM slot_facts WHERE kind='prose' AND cohort BETWEEN 2004 AND 2024 GROUP BY CAST(cohort AS CHAR),duration UNION ALL SELECT 'slot' endpoint,'editor' dimension,editor_group grp,duration,COUNT(*) exits,SUM(event) deaths FROM slot_facts WHERE kind='prose' GROUP BY editor_group,duration UNION ALL SELECT 'slot' endpoint,'length' dimension,length_bucket grp,duration,COUNT(*) exits,SUM(event) deaths FROM slot_facts WHERE kind='prose' GROUP BY length_bucket,duration UNION ALL SELECT 'slot' endpoint,'kind' dimension,kind grp,duration,COUNT(*) exits,SUM(event) deaths FROM slot_facts WHERE 1=1 GROUP BY kind,duration;
